    out=a[0].get(q,0)
    for e,v in a[1].items():
        if q>=e and (q-e)%H==0: out+=v*hcoef((q-e)//H)
    return out%P

def hcoef(n):
    c=1
    for i in range(n): c=c*(1-2*i)*pow(2*(i+1),-1,P)*(-1)%P
    return c

def mon(q,c=1): return ({q:c%P},{})
